/bin/zsh -lc "python3 -c 'import csv; from collections import Counter; from datetime import datetime
p=\"/Users/leonardopadilla/Documents/USFQ/3er Semestre/Progra. Asistida de Apps/ClaseApps.worktrees/semana12-cyber-detective/Semana12/logs_sinteticos.csv\"
with open(p,newline=\"\",encoding=\"utf-8-sig\") as f:
 r=csv.DictReader(f); cols=[c for c in (r.fieldnames or []) if c.strip().lower() in (\"timestamp\",\"datetime\",\"date_time\",\"fecha_hora\",\"fecha\",\"time\",\"event_time\",\"event_timestamp\")]; counts=Counter(); invalid=0
 if not cols: print(\"No se encontró una columna temporal reconocida; no se imprimieron datos.\")
 else:
  for row in r:
   try:
    dt=datetime.fromisoformat(row.get(cols[0],\"\").strip().replace(\"Z\",\"+00:00\")); counts[dt.strftime(\"%Y-%m-%d %H:00\")]+=1
   except (ValueError,TypeError): invalid+=1
  for hour,n in sorted(counts.items()): print(hour,\"|\",n)
  print(\"TOTAL |\",sum(counts.values())); print(\"FECHAS_NO_INTERPRETABLES |\",invalid)
'"

